"""Exact pet and Xeno data exported from the user-supplied sIO runtime.

The JSON is zlib-compressed only to keep generated source compact and prevent
manual JSON corruption.
"""
from __future__ import annotations

import base64
import json
import zlib

_COMPRESSED = "" 
SIO_PET_DATA = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED)).decode("utf-8"))
